package vn.codegym;
import jakarta.servlet.annotation.WebServlet;import jakarta.servlet.http.*;import java.io.*;
@WebServlet("/login") public class LoginServlet extends HttpServlet{protected void doGet(HttpServletRequest r,HttpServletResponse s)throws IOException{s.setContentType("text/html;charset=UTF-8");s.getWriter().print("<form method='post'><input name='username' placeholder='Tên đăng nhập' required><input type='password' name='password' required><button>Đăng nhập</button></form>");}protected void doPost(HttpServletRequest r,HttpServletResponse s)throws IOException{s.setContentType("text/html;charset=UTF-8");String u=r.getParameter("username"),p=r.getParameter("password");s.getWriter().printf("%s",("admin".equals(u)&&"123456".equals(p))?"<h1>Xin chào "+u+"!</h1>":"<h1>Đăng nhập thất bại</h1>");}}
